"""Per-agent test doubles for micro agents (issue #39).

Production deleted ``_run_rule_engine``. These doubles reproduce the former
deterministic builders so tests keep asserting meaningful content — not empty
``output_model()`` defaults.
"""

from __future__ import annotations

import importlib
import textwrap
from typing import Callable

from pydantic import BaseModel

from labpilot.accessor.common.micro_agents import StructuredContext

Builder = Callable[[StructuredContext], BaseModel]

