_BUILDER_CACHE: dict[str, Builder] = {}


def _builder_for_name(class_name: str, module_path: str) -> Builder:
    cached = _BUILDER_CACHE.get(class_name)
    if cached is not None:
        return cached
    mod_path, body = _BODIES[class_name]

    def builder(context: StructuredContext) -> BaseModel:
        # Prefer the live module of the already-imported agent class path.
        mod = importlib.import_module(module_path)
        ns = dict(mod.__dict__)
        code = "def _build(context):\n" + textwrap.indent(body, "    ")
        exec(compile(code, f"<double:{class_name}>", "exec"), ns)
        return ns["_build"](context)

    _BUILDER_CACHE[class_name] = builder
    return builder


def resolve_builder(agent_cls: type) -> Builder | None:
    """Return a context→model builder for this agent class, if we have one."""
    name = agent_cls.__name__
    # ReflectionGeneratorAgent is an alias of RootCauseAgent.
    if name not in _BODIES and name == "ReflectionGeneratorAgent":
        name = "RootCauseAgent"
    if name not in _BODIES:
        return None
    return _builder_for_name(name, agent_cls.__module__)


class AgentDoubleClient:
    """LLM-shaped client; ``complete`` returns meaningful per-agent JSON."""

    def __init__(self, agent_cls: type) -> None:
        self.agent_cls = agent_cls
        self._context: StructuredContext | None = None
        self.last_served: object | None = None
        self.calls = 0

    def bind(self, context: StructuredContext) -> None:
        self._context = context

    def complete(self, system: str, user: str, *, json_mode: bool = False) -> str:
        self.calls += 1
        builder = resolve_builder(self.agent_cls)
        if builder is None:
            model_cls = getattr(self.agent_cls, "output_model", None)
            if model_cls is None:
                raise RuntimeError(f"no double registered for {self.agent_cls!r}")
            return model_cls().model_dump_json()
        if self._context is None:
            raise RuntimeError("AgentDoubleClient.complete called before bind()")
        return builder(self._context).model_dump_json()


def double_for(agent_cls: type) -> AgentDoubleClient:
    return AgentDoubleClient(agent_cls)


def known_double_names() -> frozenset[str]:
    return frozenset(_BODIES)
